practice.solution:
count = int(input())
for i in range(count):
    k = int(input())
    step = int(input())
    total = int(input())
    offset = step * k * (k - 1) // 2
    print(f"Problem {i + 1}: {k}n + {offset} = {total}")
    nums = []
    if (total - offset) % k == 0:
        n = (total - offset) // k
        for j in range(k):
            nums.append(n + step * j)
    if len(nums) == 0:
        print("  no such integers")
    else:
        print(f"  {nums}")
